826		\begin{align*}
827			\mathcal{O}^{x,z,r,s} \, \mathcal{O}^{x,z,r',s'} &= \sum_{a,b,a',b'} (-1)^{a + b + a' + b'} \hat{L}^{x,z,r,s}_{a,b} \, \hat{L}^{x,z,r',s'}_{a',b'} \\
