882	\begin{lemma}\label{lem:qld-xz-lines}
883	  There exists a function $\delta_P(\eps,m,d,q) = \poly(\eps,
884	  md/q)$ such that the following holds. For $\mH \in \{\mH_\alice,\mH_\bob\}$ and for every pair of lines $\line_X$ and $\line_Z$ there exists a POVM $\{T^{\line_X, \line_Z}_{f_X, f_Z}\}$ acting on
885	  $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ with answers
886	  consisting of pairs of polynomials $f_X, f_Z$ in $\deg_{md}(\line_X)
887	  \times \deg_{md}(\line_Z)$
888	  such that on average over pairs $(\line_X, x)$ and $(\line_Z, z)$
889	  independently sampled from the line-point distribution,
890	  \begin{align*}
891	    (T^{\line_X, \line_Z}_{[ \eval_x(\cdot) =a, \eval_z(\cdot) = b]})_{\alice \alice'} &\simeq_{\delta_P} (\hat{Q}^{x,z}_{a, b})_{\bob \alice''}, \\
892	\end{align*}
893	  as well as all symmetric equivalents of this approximation. Moreover, if $\line_W$ is axis-parallel, then $f_W \in \deg_{d}(\line_W)$.
894	\end{lemma}
895	
896	\begin{proof}
897	  We construct the required measurements by combining the measurements
898	  $\hat{M}^{(\Line,W),\line_W}_{f_W}$ for $W \in \{X, Z\}$. For convenience in the proof we slightly abuse the notation $\approx_\delta$ to mean $\approx_{\poly(\eps)}$ for some polynomial function $\delta=\poly(\eps)$ that may differ each time the notation is used.
899	
900	  	We first argue that the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ obtained in Lemma~\ref{lem:qld-4-10} are consistent with the $\{\hat{M}^{(\Line,W),\line_W}_{f_W} \}$. 
901	
902		Applying Fact~\ref{fact:add-a-proj} to~\eqref{eq:qld-q-cons-m-hat-zx}, we get that on average over uniformly random $x,z$,
903		\begin{align}
904			\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}
905	&=	\Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}\cdot	\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \notag\\
906	& \approx_\delta \Big (\hat{M}^{(\Point,\zpt),z}_{b} \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''} \notag\\
907	&\approx_\delta \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'}\;.\notag
908		\end{align}
909		Since $\{\hat{Q}^{x,z}_{a,b}\}$ is a projective measurement, applying \Cref{lem:cool-closeness-fact} with $(\hat{Q}^{x,z}_{a,b})_{\alice, \alice'}$ playing the role of $A^{x}_a$ and $(\hat{Q}^{x,z}_{a,b} )_{\alice, \alice'} \cdot (\hat{M}^{(\Point, \zpt), z}_{b})_{\bob \alice''}$ playing the role of $B^{x}_a$, we obtain that
910		\begin{equation}
911		\Big( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \approx_\delta \sum_b \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}\;.\label{eq:qqm}
912		\end{equation}
913		We now show that on average over uniformly random $x,z$, 
914		\begin{equation}
915		\label{eq:qld-qxz-close-to-point}
916		\Big ( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \approx_{\delta_Q} \Big (\hat{M}^{(\Point,X),x}_{a} \Big)_{\bob \alice''} \;.
917		\end{equation}
918		This follows from~\eqref{eq:qqm} and the following calculation:
919		\begin{align*}
920			&\E_{x,z} \sum_a \norm{ \sum_b  \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \ket{\hat{\psi}} }^2  \\
921			&=\E_{x,z} \sum_a \norm{ \sum_b \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
922			&= \E_{x,z} \sum_{a,b}  \norm{  \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
923	                &= \E_{x,z} \sum_{a,b} \norm{ \Big(  \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
924	                &\leq \E_{x,z} \sum_{a,b} \norm{ \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
